rule "omni-v5-ad-asrep-preparation"
when
  (to_string($message.winlogbeat_winlog_event_id) == "4738" &&
   regex("(?i)(%%2096|pr[ée]-?auth[^\\n]*(activ|enabl))", to_string($message.winlogbeat_winlog_event_data_UserAccountControl)).matches == true) ||
  (to_string($message.winlogbeat_winlog_event_id) == "5136" &&
   to_string($message.winlogbeat_winlog_event_data_AttributeLDAPDisplayName) == "userAccountControl" &&
   to_string($message.winlogbeat_winlog_event_data_OperationType) == "%%14674" &&
   (to_long($message.winlogbeat_winlog_event_data_AttributeValue, 0) / 4194304) % 2 == 1)
then
  set_field("v5_tag", "asrep_preparation");
  set_field("v5_severite", "ELEVE");
  set_field("v5_mitre", "T1558.004");
  set_field("v5_entite", lowercase(to_string($message.winlogbeat_winlog_event_data_SubjectUserName)));
  set_field("v5_detail", concat("Pre-authentification Kerberos retiree : ", to_string($message.winlogbeat_winlog_event_data_TargetUserName, to_string($message.winlogbeat_winlog_event_data_ObjectDN))));
end

rule "omni-v5-ad-canari-fichier"
when
  (to_string($message.winlogbeat_winlog_event_id) == "4663" || to_string($message.winlogbeat_winlog_event_id) == "5145") &&
  (ends_with(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectName)), "\\exemple - canari 1.xlsx") ||
   ends_with(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectName)), "\\exemple - canari 2.kdbx") ||
   ends_with(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectName)), "\\exemple - canari 3.xlsx")) &&
  to_string($message.winlogbeat_winlog_event_data_SubjectUserSid) != "S-1-5-18" &&
  !ends_with(to_string($message.winlogbeat_winlog_event_data_SubjectUserName), "$")
then
  set_field("v5_tag", "canari_fichier");
  set_field("v5_severite", "CRITIQUE");
  set_field("v5_mitre", "T1083");
  set_field("v5_entite", lowercase(to_string($message.winlogbeat_winlog_event_data_SubjectUserName)));
  set_field("v5_detail", concat("Fichier canari ouvert : ", to_string($message.winlogbeat_winlog_event_data_ObjectName)));
end

rule "omni-v5-ad-gpo-sensible"
when
  to_string($message.winlogbeat_winlog_event_id) == "5136" &&
  ((lowercase(to_string($message.winlogbeat_winlog_event_data_AttributeLDAPDisplayName)) == "gplink" &&
    (lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectClass)) == "domaindns" || starts_with(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectDN)), "ou=domain controllers,"))) ||
   (lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectClass)) == "grouppolicycontainer" &&
    (to_string($message.winlogbeat_winlog_event_data_SubjectUserSid) == "S-1-5-18" || ends_with(to_string($message.winlogbeat_winlog_event_data_SubjectUserName), "$")) &&
    !contains(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectDN)), "{00000000-0000-0000-0000-000000000000}")))
then
  set_field("v5_tag", "gpo_sensible");
  set_field("v5_severite", "ELEVE");
  set_field("v5_mitre", "T1484.001");
  set_field("v5_entite", lowercase(to_string($message.winlogbeat_winlog_event_data_SubjectUserName)));
  set_field("v5_detail", concat(concat(to_string($message.winlogbeat_winlog_event_data_AttributeLDAPDisplayName), " modifie sur "), to_string($message.winlogbeat_winlog_event_data_ObjectDN)));
end

rule "omni-v5-ad-kerberoast-aes"
when
  to_string($message.winlogbeat_winlog_event_id) == "4769" &&
  to_string($message.winlogbeat_winlog_event_data_Status) == "0x0" &&
  has_field("winlogbeat_winlog_event_data_ServiceName") &&
  !contains(to_string($message.winlogbeat_winlog_event_data_ServiceName), "$") &&
  !starts_with(lowercase(to_string($message.winlogbeat_winlog_event_data_ServiceName)), "krbtgt") &&
  lowercase(to_string($message.winlogbeat_winlog_event_data_ServiceName)) != "svc-exemple-leurre" &&
  lowercase(to_string($message.winlogbeat_winlog_event_data_ServiceName)) != lowercase(to_string(regex("^([^@]+)", to_string($message.winlogbeat_winlog_event_data_TargetUserName), ["u"])["u"]))
then
  set_field("v5_tag", "kerberoast_aes");
  set_field("v5_severite", "ELEVE");
  set_field("v5_mitre", "T1558.003");
  set_field("v5_entite", lowercase(to_string($message.winlogbeat_winlog_event_data_TargetUserName)));
  set_field("v5_detail", concat("TGS vers le compte utilisateur ", to_string($message.winlogbeat_winlog_event_data_ServiceName)));
end

rule "omni-v5-ad-leurre-svc-exemple-leurre"
when
  lowercase(to_string($message.winlogbeat_winlog_event_data_TargetUserName)) == "svc-exemple-leurre" ||
  starts_with(lowercase(to_string($message.winlogbeat_winlog_event_data_TargetUserName)), "svc-exemple-leurre@") ||
  lowercase(to_string($message.winlogbeat_winlog_event_data_ServiceName)) == "svc-exemple-leurre" ||
  lowercase(to_string($message.winlogbeat_winlog_event_data_SubjectUserName)) == "svc-exemple-leurre" ||
  contains(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectDN)), "cn=svc-exemple-leurre,")
then
  set_field("v5_tag", "leurre_svc_exemple_leurre");
  set_field("v5_severite", "CRITIQUE");
  set_field("v5_mitre", "T1558.003");
  set_field("v5_entite", lowercase("svc-exemple-leurre"));
  set_field("v5_detail", concat(concat("Evenement ", to_string($message.winlogbeat_winlog_event_id)), " sur le compte leurre"));
end

rule "omni-v5-ad-shadow-credentials"
when
  to_string($message.winlogbeat_winlog_event_id) == "5136" &&
  lowercase(to_string($message.winlogbeat_winlog_event_data_AttributeLDAPDisplayName)) == "msds-keycredentiallink" &&
  lowercase(to_string($message.winlogbeat_winlog_event_data_SubjectUserName)) != "msol_0123456789ab" &&
  !(ends_with(to_string($message.winlogbeat_winlog_event_data_SubjectUserName), "$") &&
    starts_with(lowercase(to_string($message.winlogbeat_winlog_event_data_ObjectDN)), concat(concat("cn=", lowercase(regex_replace("\\$$", to_string($message.winlogbeat_winlog_event_data_SubjectUserName), ""))), ",")))
then
  set_field("v5_tag", "shadow_credentials");
  set_field("v5_severite", "CRITIQUE");
  set_field("v5_mitre", "T1556");
  set_field("v5_entite", lowercase(to_string($message.winlogbeat_winlog_event_data_SubjectUserName)));
  set_field("v5_detail", concat("msDS-KeyCredentialLink modifie sur ", to_string($message.winlogbeat_winlog_event_data_ObjectDN)));
end

rule "omni-v5-m365-mfa-defi"
when
  to_string($message.event_source) == "m365" &&
  to_string($message.m365_type) == "signin" &&
  (to_string($message.m365_fail_code) == "50074" || to_string($message.m365_fail_code) == "50076" || to_string($message.m365_fail_code) == "500121")
then
  set_field("v5_tag", "m365_mfa_defi");
  set_field("v5_severite", "ELEVE");
  set_field("v5_mitre", "T1621");
  set_field("v5_entite", lowercase(to_string($message.user)));
  set_field("v5_detail", concat(concat(concat("Defi MFA ", to_string($message.m365_fail_code)), concat(" depuis ", to_string($message.src_country))), concat(" app ", to_string($message.app))));
  set_field("v5_mfa_etranger", to_string($message.src_country) != "FR" && to_string($message.src_country) != "");
end

rule "omni-v5-m365-regle-boite-suspecte"
when
  to_string($message.event_source) == "m365" &&
  (to_string($message.event_action) == "New-InboxRule" || lowercase(to_string($message.event_action)) == "set-inboxrule" ||
   to_string($message.event_action) == "UpdateInboxRules") &&
  ((has_field("src_ip_country_code") && to_string($message.src_ip_country_code) != "FR" && to_string($message.src_ip_country_code) != "") ||
   (to_string($message.event_action) != "UpdateInboxRules" && has_field("object") &&
    regex("\\\\([^A-Za-z0-9]*|.{1,2})$", to_string($message.object)).matches == true))
then
  set_field("v5_tag", "m365_regle_boite_suspecte");
  set_field("v5_severite", "ELEVE");
  set_field("v5_mitre", "T1564.008");
  set_field("v5_entite", lowercase(to_string($message.user)));
  set_field("v5_detail", concat(concat(concat(to_string($message.event_action), " "), to_string($message.object)), concat(" depuis ", to_string($message.src_ip_country_code))));
end

rule "omni-v5-m365-transfert-externe"
when
  to_string($message.event_source) == "m365" &&
  (has_field("forward_external") ||
   (has_field("fwd_target") &&
    regex("(?i)@(omnitech-security\\.fr|omnitech\\.security|omnitechsecurity\\.onmicrosoft\\.com|invissys\\.com)\\s*$", to_string($message.fwd_target)).matches == false))
then
  set_field("v5_tag", "m365_transfert_externe");
  set_field("v5_severite", "ELEVE");
  set_field("v5_mitre", "T1114.003");
  set_field("v5_entite", lowercase(to_string($message.user)));
  set_field("v5_detail", concat(concat(concat(to_string($message.event_action), " sur "), to_string($message.object)), concat(" vers ", to_string($message.fwd_target))));
end
